def compute_contamination(N, x1, y1, x2, y2):
    """Compute contamination levels for a grid of size N x N"""
    contamination = [[0] * N for _ in range(N)]

    for i in range(N):
        for j in range(N):
            # Count how many corners of cell (i, j) are inside the rectangle
            count = 0

            # Check 4 corners of cell (i, j)
            # Cell (i, j) has corners at:
            # (i, j) - top-left
            # (i+1, j) - top-right
            # (i, j+1) - bottom-left
            # (i+1, j+1) - bottom-right

            # Check if each corner is inside or on the border of the rectangle
            if x1 <= i <= x2 and y1 <= j <= y2:
                count += 1
            if x1 <= i+1 <= x2 and y1 <= j <= y2:
                count += 1
            if x1 <= i <= x2 and y1 <= j+1 <= y2:
                count += 1
            if x1 <= i+1 <= x2 and y1 <= j+1 <= y2:
                count += 1

            contamination[i][j] = count

    return contamination

def solve() -> None:
    N = int(input().strip())

    # Read the contamination pattern
    pattern = []
    for _ in range(N):
        line = input().strip()
        pattern.append([int(c) for c in line])

    # Try all possible rectangles
    for x1 in range(N):
        for y1 in range(N):
            for x2 in range(x1 + 1, N):
                for y2 in range(y1 + 1, N):
                    # Compute contamination for this rectangle
                    contam = compute_contamination(N, x1, y1, x2, y2)

                    # Check if it matches the pattern
                    match = True
                    for i in range(N):
                        for j in range(N):
                            if contam[i][j] != pattern[i][j]:
                                match = False
                                break
                        if not match:
                            break

                    if match:
                        print("Yes")
                        return

    print("No")

solve()
