def is_corner_inside(x, y, x1, y1, x2, y2):
    """Check if a corner (x, y) is inside or on the border of the rectangle."""
    return x1 <= x <= x2 and y1 <= y <= y2


def count_contamination_levels(grid, x1, y1, x2, y2, N):
    """Count how many corners of each cell are inside the rectangle."""
    contamination = [[0 for _ in range(N)] for _ in range(N)]

    for i in range(N):  # row in the grid (y-coordinate)
        for j in range(N):  # column in the grid (x-coordinate)
            # Corners of the cell at (j, N - i)
            corners = [
                (j, N - i),          # bottom-left
                (j + 1, N - i),      # bottom-right
                (j, N - i + 1),      # top-left
                (j + 1, N - i + 1)   # top-right
            ]

            count = 0
            for (x, y) in corners:
                if is_corner_inside(x, y, x1, y1, x2, y2):
                    count += 1
            contamination[i][j] = count

    return contamination


def solve(grid, N):
    """Check if there exists a rectangle that produces the contamination pattern."""
    # Try all possible rectangles
    for x1 in range(N):
        for y1 in range(N):
            for x2 in range(x1 + 1, N + 1):
                for y2 in range(y1 + 1, N + 1):
                    # Calculate contamination levels for this rectangle
                    contamination = count_contamination_levels(grid, x1, y1, x2, y2, N)

                    # Check if it matches
                    match = True
                    for i in range(N):
                        for j in range(N):
                            if contamination[i][j] != int(grid[i][j]):
                                match = False
                                break
                        if not match:
                            break

                    if match:
                        return "Yes"

    return "No"

# Read input
N = int(input())
grid = []
for _ in range(N):
    line = input().strip()
    grid.append(line)

# Solve and print result
print(solve(grid, N)
"}

