    a = list(map(int, input().split()))

    # Count frequencies
    freq = {}
    for num in a:
        freq[num] = freq.get(num, 0) + 1

    # Check if any element appears at least three times
    has_three_of_same = any(count >= 3 for count in freq.values())

    # Check if there's a palindrome of length 3
    # For a palindrome [a, b, a], we need two a's with some b in between
    has_length_3 = False
    for num, count in freq.items():
        if count >= 2:
            # Find if there's another number between the two occurrences of num
            # Find all indices where num appears
            indices = [i for i, val in enumerate(a) if val == num]
            if len(indices) >= 2:
                # Check if there's another number between these two indices
                for i in range(1, len(indices)):
                    # Check if there's at least one other number between indices[i-1] and indices[i]
                    # The middle element can be any number between them
                    # But we need to check if there's at least one number in between
                    if indices[i] - indices[i-1] > 1:
                        has_length_3 = True
                        break
                if has_length_3:
                    break

    # Check if there's a palindrome of length 4
    # For a palindrome [a, b, b, a], we need two pairs of equal elements
    has_length_4 = False
    if len(freq) >= 2:
        counts = list(freq.values())
        # Check if there are at least two elements with count >= 2
        has_length_4 = sum(1 for count in counts if count >= 2) >= 2

    # If either is true, answer is YES
    if has_three_of_same or has_length_3 or has_length_4:
        print("YES")
    else:
        print("NO")
