import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Find nearest smaller to the left
    L = [-1] * n
    stack = []
    for i in range(n):
        while stack and a[stack[-1]] >= a[i]:
            stack.pop()
        if stack:
            L[i] = stack[-1]
        else:
            L[i] = -1
        stack.append(i)

    # Find nearest smaller or equal to the right
    R = [n] * n
    stack = []
    for i in range(n-1, -1, -1):
        while stack and a[stack[-1]] > a[i]:
            stack.pop()
        if stack:
            R[i] = stack[-1]
        else:
            R[i] = n
        stack.append(i)

    # Update answer array
    ans = [0] * n
    for i in range(n):
        size = i - L[i] - 1
        r = R[i]
        for j in range(size, r):
            ans[j] = max(ans[j], a[i])

    print(' '.join(map(str, ans)))

if __name__ == '__main__':
    solve()
