q = int(input())

for _ in range(q):
    n = int(input())
    p = list(map(int, input().split()))

    # Find positions of students 1, 2, ..., n
    positions = [0] * (n + 1)
    for i in range(n):
        positions[p[i]] = i

    # Check clockwise round dance
    clockwise = True
    for i in range(1, n):
        # Student i should be followed by student i+1
        # In clockwise order, position[i] should be followed by position[i+1]
        if (positions[i+1] - positions[i] - 1) % n != 0:
            clockwise = False
            break

    # Check counterclockwise round dance
    counterclockwise = True
    for i in range(1, n):
        # Student i should be followed by student i+1 in counterclockwise order
        # In counterclockwise order, position[i+1] should be followed by position[i]
        if (positions[i] - positions[i+1] - 1) % n != 0:
            counterclockwise = False
            break

    if clockwise or counterclockwise:
        print("YES")
    else:
        print("NO")
"}

