# Count frequency of each topic
from collections import Counter
freq = Counter(a)

# Sort topics by frequency (descending)
topics = sorted(freq.values(), reverse=True)

# dp[i] = maximum number of problems we can use if the last contest used i problems
dp = {}

# Initialize: we can start with any number of problems from the first topic
for k in range(topics[0] + 1):
    dp[k] = k

# Process remaining topics
for f in topics[1:]:
    new_dp = {}

    # Try not using this topic at all
    new_dp.update(dp)

    # Try using this topic with some count k (0 ≤ k ≤ f)
    for k in range(f + 1):
        # Try all previous states
        for prev, total in dp.items():
            if prev * 2 <= k:
                new_total = total + k
                if k not in new_dp or new_dp[k] < new_total:
                    new_dp[k] = new_total

    dp = new_dp

# Find the maximum total problems
print(max(dp.values()))
"}

