n = int(input())
parts = []
for _ in range(n):
    s, g = map(int, input().split())
    parts.append((s, g))

# Initialize DP
# dp[i][s] = maximum total lawn removed to achieve road width s at position i
# We'll use a dictionary of dictionaries for efficiency

dp = [{} for _ in range(n)]
dp[0] = {s: 0 for s in range(parts[0][0], parts[0][0] + parts[0][1] + 1)}

for i in range(1, n):
    s_i, g_i = parts[i]
    for s in range(s_i, s_i + g_i + 1):
        # Check if we can reach s from any of the previous positions
        max_lawn = 0
        for prev_s in [s-1, s, s+1]:
            if prev_s in dp[i-1]:
                max_lawn = max(max_lawn, dp[i-1][prev_s])
        dp[i][s] = max_lawn + (s - s_i)

# Find the maximum total lawn removed
if not dp[n-1]:
    print(-1)
else:
    max_lawn = max(dp[n-1].values())
    print(max_lawn)

    # Reconstruct the path
    path = [0] * n
    for s in dp[n-1]:
        if dp[n-1][s] == max_lawn:
            path[n-1] = s
            break

    for i in range(n-2, -1, -1):
        s = path[i+1]
        for prev_s in [s-1, s, s+1]:
            if dp[i][prev_s] == dp[i+1][s] - (s - parts[i][0]):
                path[i] = prev_s
                break

    print(' '.join(map(str, path)))
"}

