def solve():
    n, m = map(int, input().split())
    w = []
    for _ in range(n):
        w.append(list(map(int, input().split())))

    # Compute row differences and column differences
    row_diffs = []
    for i in range(n):
        diffs = []
        for j in range(1, m):
            diffs.append(w[i][j] - w[i][0])
        row_diffs.append(diffs)

    col_diffs = []
    for j in range(m):
        diffs = []
        for i in range(1, n):
            diffs.append(w[i][j] - w[0][j])
        col_diffs.append(diffs)

    # Find possible k values
    possible_k = set()
    # For each row, the differences between elements should be consistent modulo k
    for i in range(n):
        for j in range(1, m):
            diff = w[i][j] - w[i][0]
            possible_k.add(diff)
            possible_k.add(-diff)
    for i in range(1, n):
        for j in range(m):
            diff = w[i][j] - w[0][j]
            possible_k.add(diff)
            possible_k.add(-diff)

    # Also consider the actual values as possible k (if they're positive)
    for val in w:
        for v in val:
            if v > 0:
                possible_k.add(v)

    # Check if there's a k that works
    found = False
    for k in possible_k:
        if k <= 0:
            continue

        # Check if k works
        # For each row i, we need to find b values such that:
        # (a[i] + b[j]) % k = w[i][j] for all j
        # This means a[i] = (w[i][j] - b[j]) % k

        # Let's try to find a and b
        a = []
        b = []
        valid = True

        # Find b values using row 0
        b0 = w[0][0]
        b = [w[0][j] - b0 for j in range(m)]

        # Find a values using column 0
        a0 = w[0][0]
        a = [w[i][0] - a0 for i in range(n)]

        # Verify all values
        for i in range(n):
            for j in range(m):
                if (a[i] + b[j]) % k != w[i][j]:
                    valid = False
                    break
            if not valid:
                break

        if valid:
            found = True
            break

    if not found:
        print("NO")
    else:
        print("YES")
        print(k)
        print(' '.join(map(str, a)))
        print(' '.join(map(str, b)))

