import sys

def solve() -> None:
    # Read input
    good_letters = sys.stdin.readline().strip()
    pattern = sys.stdin.readline().strip()
    n = int(sys.stdin.readline())

    # Parse good letters
    good_set = set(good_letters)

    # Parse pattern
    star_pos = -1
    for i, ch in enumerate(pattern):
        if ch == '*':
            star_pos = i

    # Check each query
    for _ in range(n):
        query = sys.stdin.readline().strip()

        # Check if query length is valid
        if star_pos == -1:
            # No star, query length must match pattern length
            if len(query) != len(pattern):
                print("NO")
                continue
        else:
            # With star, query length must be >= pattern length
            if len(query) < len(pattern):
                print("NO")
                continue

        # Check each character
        match = True
        for i in range(len(pattern)):
            p_char = pattern[i]
            q_char = query[i] if i < len(query) else None

            if p_char == '?':
                # '?' can be replaced with any good letter
                if q_char is None or q_char not in good_set:
                    match = False
                    break
            elif p_char == '*':
                # '*' can be replaced with any string of bad letters (or empty)
                # We need to check that the corresponding part of the query consists only of bad letters
                # Find the range of characters that would be matched by '*'
                start = i + 1
                end = len(pattern) - i - 1

                # The query segment from start to end (inclusive) should be all bad letters
                for j in range(start, end + 1):
                    if j >= len(query) or query[j] in good_set:
                        match = False
                        break
                if not match:
                    break
            else:
                # Regular character, must match exactly
                if q_char is None or q_char != p_char:
                    match = False
                    break

        print("YES" if match else "NO")

if __name__ == "__main__":
    solve()
"}

