    for _ in range(t):
        n = int(input())
        S = list(map(int, input().split()))

        # dp[i] = minimum passes needed to reduce all trampolines from 1 to i to 1
        dp = [float('inf')] * (n + 2)  # dp[0] is base case
        dp[0] = 0  # 0 passes needed for nothing

        for i in range(1, n + 1):
            if S[i-1] == 1:
                # No action needed, carry forward the minimum passes
                dp[i] = dp[i-1]
            else:
                # We need to do at least one pass starting at position i
                # This pass will reduce S[i-1] by 1 and move us to i + S[i-1]
                # Then we need to continue from there
                next_pos = i + S[i-1]
                if next_pos <= n:
                    dp[i] = dp[i-1] + 1  # One pass starting at i, plus passes needed for previous
                else:
                    # The pass ends here, just need passes for previous
                    dp[i] = dp[i-1] + 1

        print(dp[n])

