    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])
    d = int(data[2])
    a = list(map(int, data[3:3+n]))

    # Sort the array
    a.sort()

    # Greedy approach
    boxes = []
    current_box = []

    for pencil in a:
        # Try to add to current box
        if current_box and abs(pencil - current_box[0]) <= d:
            current_box.append(pencil)
        else:
            # Can't add to current box, start a new box
            if len(current_box) > 0:
                boxes.append(current_box)
            current_box = [pencil]

    # Add the last box
    if current_box:
        boxes.append(current_box)

    # Check if all boxes have at least k pencils
    for box in boxes:
        if len(box) < k:
            print("NO")
            return

    print("YES")

