import sys
import math
from math import gcd
from functools import reduce


def compute_gcd(arr):
    return reduce(math.gcd, arr)

def get_divisors(n):
    divisors = set()
    for i in range(1, int(math.isqrt(n)) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return divisors


def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    arr = list(map(int, data[1:1+n]))

    g_all = compute_gcd(arr)

    min_remove = n  # We want to minimize removals

    for num in arr:
        divisors = get_divisors(num)
        for d in divisors:
            if d <= g_all:
                continue
            # Count how many numbers are multiples of d
            count = 0
            for other in arr:
                if other % d == 0:
                    count += 1
            if count > 0:
                min_remove = min(min_remove, n - count)

    if min_remove == n:
        print(-1)
    else:
        print(min_remove)

if __name__ == "__main__":
    solve()
"}

