def are_directly_reachable(p1, p2, all_points):
    # Check if p1 and p2 are directly reachable
    # They must be in the same row or column
    if p1[0] == p2[0]:  # Same column
        # Check if there are any other points in this column between them
        min_row = min(p1[1], p2[1])
        max_row = max(p1[1], p2[1])
        for point in all_points:
            if point != p1 and point != p2 and point[0] == p1[0] and min_row < point[1] < max_row:
                return False
        return True
    elif p1[1] == p2[1]:  # Same row
        # Check if there are any other points in this row between them
        min_col = min(p1[0], p2[0])
        max_col = max(p1[0], p2[0])
        for point in all_points:
            if point != p1 and point != p2 and point[1] == p1[1] and min_col < point[0] < max_col:
                return False
        return True
    return False

