def is_mirror_word(word):
    # Dictionary of characters that have valid mirror images
    mirror_map = {
        'A': 'A', 'H': 'H', 'I': 'I', 'M': 'M', 'O': 'O',
        'T': 'T', 'U': 'U', 'V': 'V', 'W': 'W', 'X': 'X', 'Y': 'Y'
    }

    # Check if all characters have valid mirror images
    for char in word:
        if char not in mirror_map:
            return False

    # Get the mirror image of each character
    mirrored = ''.join([mirror_map[char] for char in word])

    # Check if the mirrored word equals the original word
    return mirrored == word

# Read input
