def gcd(x, y):
    while y:
        x, y = y, x % y
    return x

def gcd_all(arr):
    result = arr[0]
    for num in arr[1:]:
        result = gcd(result, num)
    return result

original_gcd = gcd_all(a)

# Count how many integers are divisible by each possible divisor
div_counts = {}
for num in a:
    for d in range(1, int(num**0.5) + 1):
        if num % d == 0:
            div_counts[d] = div_counts.get(d, 0) + 1
            if d != num // d:
                div_counts[num // d] = div_counts.get(num // d, 0) + 1

# Find the best divisor d > original_gcd
max_keep = 0
for d in div_counts:
    if d > original_gcd:
        # Get all numbers divisible by d
        div_numbers = [num for num in a if num % d == 0]
        # Calculate GCD of these numbers
        current_gcd = gcd_all(div_numbers)
        if current_gcd == d:
            max_keep = max(max_keep, len(div_numbers))

if max_keep == 0:
    print(-1)
else:
    print(n - max_keep)
"}

