import sys
import math
from collections import defaultdict

def compute_gcd(arr):
    g = arr[0]
    for num in arr[1:]:
        g = math.gcd(g, num)
    return g

def get_divisors(n):
    divisors = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return divisors


def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    arr = list(map(int, data[1:1+n]))

    original_gcd = compute_gcd(arr)

    # Count how many numbers are divisible by each divisor > original_gcd
    divisor_count = defaultdict(int)

    for num in arr:
        divisors = get_divisors(num)
        for d in divisors:
            if d > original_gcd:
                divisor_count[d] += 1

    if not divisor_count:
        print(-1)
        return

    max_count = max(divisor_count.values())
    print(n - max_count)

if __name__ == "__main__":
    solve()
"}

