def get_symmetric_groups(n):
    groups = {}
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            # Find the canonical representative of the symmetric group
            center_i = (n + 1) // 2
            center_j = (n + 1) // 2
            # For a symmetric group, the representative is:
            # - (i, j) if i <= center_i and j <= center_j
            # - (n-i+1, j) if i > center_i
            # - (i, n-j+1) if j > center_j
            # - (n-i+1, n-j+1) if i > center_i and j > center_j
            if i <= center_i and j <= center_j:
                rep = (i, j)
            else:
                # Find the position that is closest to the top-left corner
                pos1 = (i, j)
                pos2 = (n - i + 1, j)
                pos3 = (i, n - j + 1)
                pos4 = (n - i + 1, n - j + 1)
                # Choose the representative
                if i > center_i:
                    rep = pos2
                elif j > center_j:
                    rep = pos3
                else:
                    rep = pos1
            if rep not in groups:
                groups[rep] = []
            groups[rep].append((i, j))
    return groups

