    # Check if placing a one at (i, j) violates clarity
    for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        ni, nj = i + di, j + dj
        if 1 <= ni <= n and 1 <= nj <= n:
            if (ni, nj) in used:
                return False
    return True

