def solve():
    n, m = map(int, input().split())
    w = []
    for _ in range(n):
        w.append(list(map(int, input().split())))

    # Check if the matrix is valid for some k
    # For row differences to be consistent modulo k:
    # (w[i][j] - w[i][0]) % k should equal (w[0][j] - w[0][0]) % k for all i, j
    # For column differences to be consistent modulo k:
    # (w[i][j] - w[0][j]) % k should equal (w[i][0] - w[0][0]) % k for all i, j

    # Get the set of differences for row 0
    row0_diffs = set()
    for j in range(1, m):
        row0_diffs.add(w[0][j] - w[0][0])

    # Get the set of differences for column 0
    col0_diffs = set()
    for i in range(1, n):
        col0_diffs.add(w[i][0] - w[0][0])

    # Check if the matrix is consistent for some k
    # If all rows have the same set of differences, and all columns have the same set of differences
    # Then they might be consistent for some k

    # Get the set of differences for all rows
    row_sets = []
    for i in range(n):
        row_set = set()
        for j in range(1, m):
            row_set.add(w[i][j] - w[i][0])
        row_sets.append(row_set)

    # Get the set of differences for all columns
    col_sets = []
    for j in range(m):
        col_set = set()
        for i in range(1, n):
            col_set.add(w[i][j] - w[0][j])
        col_sets.append(col_set)

    # Check if all rows have the same set of differences
    if len(set(tuple(row_sets[i]) for i in range(n))) != 1:
        print("NO")
        return

    # Check if all columns have the same set of differences
    if len(set(tuple(col_sets[j]) for j in range(m))) != 1:
        print("NO")
        return

    # Now find k
    # k must be greater than the maximum value in w
    max_val = max(max(row) for row in w)

    # Get all possible k values by checking differences
    # For each row, get differences and consider their divisors
    diffs = []
    for i in range(n):
        for j in range(1, m):
            diffs.append(w[i][j] - w[i][0])

    for i in range(1, n):
        for j in range(1, m):
            diffs.append(w[i][j] - w[0][j])

    candidates = set()

    for diff in diffs:
        if diff == 0:
            continue
        # Find all divisors of |diff|
        for i in range(1, abs(diff) + 1):
            if diff % i == 0:
                candidates.add(i)

    # Also consider differences between different row/column differences
    for i in range(len(diffs)):
        for j in range(i + 1, len(diffs)):
            diff = diffs[j] - diffs[i]
            if diff == 0:
                continue
            for k in range(1, abs(diff) + 1):
                if diff % k == 0:
                    candidates.add(k)

    # Try each candidate k
    for k in candidates:
        if k <= max_val:
            continue

        # Check if this k works
        # a[0] = 0 (we can always set a[0] = 0)
        # b[0] = 0 (we can always set b[0] = 0)
        a = [0] * n
        b = [0] * m

        for i in range(n):
            for j in range(m):
                a[i] = (w[i][j] - b[j]) % k

        for i in range(n):
            for j in range(m):
                b[j] = (w[i][j] - a[i]) % k

        # Check consistency
        consistent = True
        for i in range(n):
            for j in range(m):
                if (a[i] + b[j]) % k != w[i][j]:
                    consistent = False
                    break
            if not consistent:
                break

        if consistent:
            print("YES")
            print(k)
            print(' '.join(map(str, a)))
            print(' '.join(map(str, b)))
            return

    print("NO")

