            print("NO")
            continue

    # Check character by character
    match = True
    for i, ch in enumerate(pattern):
        if ch == '?':
            # '?' can be any good letter
            if query[i] not in good_set:
                match = False
                break
        elif ch == '*':
            # '*' can be any string of bad letters (or empty)
            # We'll handle this at the end
            pass
        else:
            # Regular character
            if ch != query[i]:
                match = False
                break

