n = int(input())
types = list(map(int, input().split()))
a = list(map(int, input().split()))

# Build adjacency list
adj = [[] for _ in range(n + 1)]  # 1-indexed
for i in range(1, n + 1):
    if a[i - 1] != 0:
        adj[a[i - 1]].append(i)

# For each hotel, find longest path ending at that hotel
max_length = 0
best_path = []

for hotel in range(1, n + 1):
    if types[hotel - 1] == 1:
        # Find all nodes that can reach this hotel
        reachable = set()
        queue = [hotel]
        visited = set()

        while queue:
            node = queue.pop()
            if node in visited:
                continue
            visited.add(node)
            reachable.add(node)

            # Find all predecessors
            for pred in range(1, n + 1):
                if adj[pred] and adj[pred][-1] == node:
                    queue.append(pred)

        # Now find the longest path among these reachable nodes
        # We need a path where each node (except the last) has exactly one outgoing edge
        # This is essentially finding the longest path in a DAG

        # Use dynamic programming
        dp = {}  # dp[node] = (max_length, path)

        for node in reachable:
            if node == hotel:
                dp[node] = (1, [hotel])
            else:
                max_len = 0
                best_path = []
                for pred in range(1, n + 1):
                    if adj[pred] and adj[pred][-1] == node:
                        len_pred, path_pred = dp.get(pred, (0, []))
                        if len_pred > max_len:
                            max_len = len_pred
                            best_path = path_pred[:]
                dp[node] = (max_len + 1, best_path + [node])

        if dp[hotel][0] > max_length:
            max_length = dp[hotel][0]
            best_path = dp[hotel][1]

print(max_length)
print(' '.join(map(str, best_path)))
