from itertools import permutations

def count_inversions(seq):
    """Count the number of inversions in a sequence."""
    inversions = 0
    for i in range(len(seq)):
        for j in range(i + 1, len(seq)):
            if seq[i] > seq[j]:
                inversions += 1
    return inversions

def is_subsequence(seq, target):
    """Check if seq is a subsequence of target."""
    it = iter(target)
    return all(c in it for c in seq)

def solve():
    n = int(input())
    lescha = input().split()

    m = int(input())
    archive = []
    for i in range(m):
        parts = input().split()
        k = int(parts[0])
        words = parts[1:]
        archive.append((k, words))

    best_similarity = -1
    best_index = -1

    for idx, (k, words) in enumerate(archive, 1):
        # Try all permutations of Lesha's words
        min_inversions = float('inf')
        for perm in permutations(lescha):
            # Check if this permutation is a subsequence
            if is_subsequence(perm, words):
                inv = count_inversions(perm)
                if inv < min_inversions:
                    min_inversions = inv

        if min_inversions != float('inf'):
            # Calculate similarity
            similarity = (n * (n - 1)) // 2 - min_inversions
            if similarity > best_similarity or (similarity == best_similarity and idx < best_index):
                best_similarity = similarity
                best_index = idx

    if best_index == -1:
        print("Brand new problem!")
    else:
        print(best_index)
        print(f"[:{'=' * best_similarity}:]")

solve()
