from itertools import permutations

def is_subsequence(perm, archive):
    """Check if permutation 'perm' is a subsequence of 'archive'"""
    it = iter(archive)
    return all(word in it for word in perm)

def count_inversions(perm, original_order):
    """Count inversions in permutation relative to original order"""
    inversions = 0
    for i in range(len(perm)):
        for j in range(i + 1, len(perm)):
            if original_order.index(perm[i]) > original_order.index(perm[j]):
                inversions += 1
    return inversions

def solve():
    n = int(input())
    les = input().split()

    m = int(input())
    archive = []
    for i in range(m):
        parts = input().split()
        k = int(parts[0])
        words = parts[1:]
        archive.append((words,))

    best_problem = None
    best_similarity = float('inf')  # We want the largest similarity

    for idx, (words,) in enumerate(archive, 1):
        # Try all permutations of Lesha's words
        min_inversions = float('inf')
        for perm in permutations(les):
            if is_subsequence(perm, words):
                inv = count_inversions(perm, les)
                if inv < min_inversions:
                    min_inversions = inv

        if min_inversions != float('inf'):
            similarity = (n * (n - 1)) // 2 - min_inversions
            # We want the largest similarity
            if similarity > best_similarity:
                best_similarity = similarity
                best_problem = idx

    if best_problem is None:
        print("Brand new problem!")
    else:
        print(best_problem)
        print(f"[:{'|'*best_similarity}:]")

solve()
"}

