import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])
    d = int(data[2])
    a = list(map(int, data[3:3+n]))

    # Sort the array
    a.sort()

    # Try to fill boxes greedily
    result = "YES"

    # Current box start index
    start = 0

    for i in range(n):
        # Try to add a[i] to the current box
        if i - start + 1 >= k:
            # Current box is full, need to start new
            start = i
        else:
            # Check if we can add to current box
            if abs(a[i] - a[start]) <= d:
                continue
            else:
                # Can't add to current box, try to start new
