    while stack and a[stack[-1]] > a[i]:
        stack.pop()
    if stack:
        R[i] = stack[-1] + 1
    else:
        R[i] = n + 1
    stack.append(i)

# Calculate maximum strength for each group size
ans = [0] * (n + 1)
for i in range(n):
    size = i - L[i] - R[i] + 1
    if size > 0:
        ans[size] = max(ans[size], a[i])

