A1, B1, C1 = map(int, input().split())
A2, B2, C2 = map(int, input().split())

# Determine if line 1 is valid
if A1 == 0 and B1 == 0:
    if C1 == 0:
        # Line 1 is the entire plane
        line1_entire_plane = True
    else:
        # Line 1 is empty
        line1_entire_plane = False
else:
    line1_entire_plane = False

# Determine if line 2 is valid
if A2 == 0 and B2 == 0:
    if C2 == 0:
        # Line 2 is the entire plane
        line2_entire_plane = True
    else:
        # Line 2 is empty
        line2_entire_plane = False
else:
    line2_entire_plane = False

if line1_entire_plane and line2_entire_plane:
    # Both are entire plane, intersection is entire plane
    print(-1)
    exit()

if line1_entire_plane:
    # Line 1 is entire plane, intersection is line 2
    if A2 == 0 and B2 == 0 and C2 != 0:
        # Line 2 is empty
        print(0)
    else:
        # Line 2 is valid (non-empty)
        print(1 if A2 != 0 or B2 != 0 else 0)
        exit()

if line2_entire_plane:
    # Line 2 is entire plane, intersection is line 1
    if A1 == 0 and B1 == 0 and C1 != 0:
        # Line 1 is empty
        print(0)
    else:
        # Line 1 is valid (non-empty)
        print(1 if A1 != 0 or B1 != 0 else 0)
        exit()

# Both lines are valid
if A1 * B2 == A2 * B1:
    # Lines are parallel or coincident
    if A1 * C2 == A2 * C1:
        # Lines are coincident
        print(-1)
    else:
        # Lines are parallel but distinct
        print(0)
else:
    # Lines intersect at exactly one point
    print(1)
