import math

g = 0
for _ in range(int(input())):
    g = math.gcd(g, int(input()))

# Find all divisors of all numbers
max_val = 15000000
# Find all divisors of the original GCD and also check some other values

def get_divisors(n):
    """Get all divisors of n"""
    divisors = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return divisors

def get_all_divisors(numbers):
    """Get all divisors of all numbers"""
    divisors = set()
    for num in numbers:
        divisors.update(get_divisors(num))
    return divisors

numbers = [int(input()) for _ in range(int(input()))]
original_gcd = g

# Get all divisors of all numbers
all_divisors = get_all_divisors(numbers)

# Check if we can achieve a GCD greater than original_gcd
min_remove = -1
for d in all_divisors:
    if d <= original_gcd:
        continue

    # Check if we can achieve GCD d
    # Select all numbers divisible by d
    count = 0
    for num in numbers:
        if num % d == 0:
            count += 1

    # Calculate GCD of those numbers
    current_gcd = 0
    for num in numbers:
        if num % d == 0:
            current_gcd = math.gcd(current_gcd, num)

    if current_gcd > original_gcd:
        min_remove = min(min_remove, len(numbers) - count) if min_remove != -1 else len(numbers) - count

print(min_remove)
"}

