import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    x = [int(next(it)) for _ in range(n)]
    v = [int(next(it)) for _ in range(n)]

    total = 0
    for i in range(n):
        for j in range(i + 1, n):
            dx = x[i] - x[j]
            dv = v[i] - v[j]
            if v[i] == v[j] or dx * dv >= 0:
                total += abs(dx)

    print(total)

if __name__ == "__main__":
    solve()
"}

