import sys

def is_valid_date(date_str):
    """Check if a date string is valid"""
    # Format: dd-mm-yyyy
    if len(date_str) != 10:
        return False

    # Check format: day, month, year parts
    if date_str[2] != '-' or date_str[5] != '-':
        return False

    day_str = date_str[0:2]
    month_str = date_str[3:5]
    year_str = date_str[6:10]

    try:
        day = int(day_str)
        month = int(month_str)
        year = int(year_str)
    except ValueError:
        return False

    # Check if the year is between 2013 and 2015
    if year < 2013 or year > 2015:
        return False

    # Check if the month is valid
    if month < 1 or month > 12:
        return False

    # Check if the day is valid
    valid_days = {1: 31, 2: 28, 3: 31, 4: 30, 5: 31, 6: 30, 7: 31, 8: 31, 9: 30, 10: 31, 11: 30, 12: 31}
    if day < 1 or day > valid_days[month]:
        return False

    return True

def solve():
    prophesy = sys.stdin.read().strip()

    date_count = {}

    # Check all substrings of length 10
    for i in range(len(prophesy) - 9):
        substring = prophesy[i:i+10]

        if is_valid_date(substring):
            date_count[substring] = date_count.get(substring, 0) + 1

    # Find the date with maximum count
    max_count = -1
    apocalypse_date = ""

    for date, count in date_count.items():
        if count > max_count:
            max_count = count
            apocalypse_date = date

    print(apocalypse_date)

if __name__ == "__main__":
    solve()
"}

