    p = list(map(int, input().split()))

    # Check if [1, 2, 3, ..., n] appears consecutively in clockwise order
    clockwise = False
    for i in range(n):
        match = True
        for j in range(n):
            if p[(i + j) % n] != j + 1:
                match = False
                break
        if match:
            clockwise = True
            break

    # Check if [n, n-1, ..., 2, 1] appears consecutively in clockwise order
    counterclockwise = False
    for i in range(n):
        match = True
        for j in range(n):
            if p[(i + j) % n] != n - j:
                match = False
                break
        if match:
            counterclockwise = True
            break

    if clockwise or counterclockwise:
        print("YES")
    else:
        print("NO")
"}

