def main():
    import sys
    input = sys.stdin.read()
    data = input.split()

    if not data:
        return

    n = int(data[0])
    snow_drifts = []

    for i in range(1, 2*n + 1, 2):
        x = int(data[i])
        y = int(data[i+1])
        snow_drifts.append((x, y))

    # Build graph
    graph = {i: [] for i in range(n)}
    for i in range(n):
        for j in range(i + 1, n):
            if snow_drifts[i][0] == snow_drifts[j][0] or snow_drifts[i][1] == snow_drifts[j][1]:
                graph[i].append(j)
                graph[j].append(i)

    # Find connected components using DFS
    visited = [False] * n
    components = 0

    for i in range(n):
        if not visited[i]:
            components += 1
            stack = [i]
            visited[i] = True

            while stack:
                node = stack.pop()
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)

    print(components - 1)

if __name__ == "__main__":
    main()
